(()=>{'use strict';const M=MartinsMateriais,J=MartinsJornada,$=id=>document.getElementById(id);const css=document.createElement('style');css.textContent='#martins-acessos{display:none!important}#martins-bottom-bar>div{overflow-x:auto;gap:2px}#martins-bottom-bar button{min-width:44px;min-height:52px;flex:1;padding:4px 2px}#gm-obra{background:white;border:1px solid #e2e8f0;border-radius:14px;padding:18px;margin:18px 0;color:#334155}#gm-obra h3{font-weight:800;font-size:17px}#gm-obra label{display:block;font-size:12px;font-weight:700;margin:10px 0}#gm-obra input,#gm-obra select,#gm-obra textarea{display:block;width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:8px}#gm-obra button,.gm-action{padding:10px 12px;min-height:44px;background:#0f172a;color:#fbbf24;border-radius:8px;font-weight:700;font-size:12px;margin:6px 6px 6px 0}#gm-obra .gm-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}#gm-obra td,#gm-obra th{padding:8px;border-bottom:1px solid #e2e8f0;text-align:left;font-size:12px}#gm-status{white-space:pre-wrap;font-size:12px;color:#92400e}.gm-note{font-size:12px;color:#64748b;margin:8px 0}@media(max-width:500px){#gm-obra .gm-grid{grid-template-columns:1fr}#martins-bottom-bar button span{font-size:9px!important}}@media print{#gm-obra{display:none!important}}';document.head.append(css);
const bar=$('bnav-btn-rdos')?.parentElement;for(const [kind,label,path] of [['planejamento','Planejar','M4 5h16v15H4zM8 2v6m8-6v6M4 10h16'],['conferencia','Conferir','M5 3h14v18H5zM8 8h8M8 12h4m2 4 2 2 4-4']]){if(!bar||$('gm-bottom-'+kind))continue;const b=document.createElement('button');b.type='button';b.id='gm-bottom-'+kind;b.title=kind==='planejamento'?'Planejamento e equipes':'Conferir divergências';b.className='flex flex-col items-center justify-center text-slate-400 hover:text-amber-400';b.innerHTML='<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="'+path+'"/></svg><span>'+label+'</span>';b.onclick=()=>$('ma-'+kind)?.click();bar.insertBefore(b,$('bnav-btn-vendas'));}
// A requisição pertence à Gestão; não copia campos nem itens do RDO.
for(const b of document.querySelectorAll('#form-rdo button[onclick*="abrirRequisicaoMaterialDoRdo"]'))b.remove();const oldNote=$('textarea-materiais')?.parentElement?.querySelector('.border-t');if(oldNote)oldNote.remove();
const getCatalog=()=>J.read(localStorage,M.CATALOG,INITIAL_PRODUTOS_FATOR);window.getProdutosFatorDb=getCatalog;window.saveProdutosFatorDb=rows=>J.write(localStorage,M.CATALOG,rows,localStorage.getItem(M.CATALOG));
function close(id,finished=false){if(id==='modal-cadastrar-produto-fator'&&!finished)returnToMovement=false;const modal=$(id);if(modal){modal.classList.add('hidden');modal.style.display='none';}}
window.fecharModalMovimentoEstoque=()=>close('modal-movimento-estoque');function wireClose(id){const modal=$(id);if(!modal)return;for(const b of modal.querySelectorAll('button[onclick]'))if(b.getAttribute('onclick').includes("classList.add('hidden')"))b.onclick=()=>close(id);modal.onclick=e=>{if(e.target===modal)close(id);};const box=modal.firstElementChild;if(box){box.style.maxHeight='88vh';box.style.overflowY='auto';}}
for(const id of ['modal-movimento-estoque','modal-cadastrar-produto-fator','modal-cadastrar-estoque-epi','modal-novo-pedido-compra'])wireClose(id);document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;for(const id of ['modal-cadastrar-produto-fator','modal-movimento-estoque','modal-cadastrar-estoque-epi']){const modal=$(id);if(modal&&!modal.classList.contains('hidden')&&modal.style.display!=='none'){close(id);e.preventDefault();break;}}});
let returnToMovement=false;const movementModal=$('modal-movimento-estoque');if(movementModal)movementModal.style.zIndex='10040';const productModal=$('modal-cadastrar-produto-fator');if(productModal)productModal.style.zIndex='10060';
function fillProducts(selected){const select=$('mov-produto-select'),before=selected||select?.value;if(!select)return;select.replaceChildren(new Option('Selecione um produto cadastrado',''));for(const p of getCatalog().filter(M.isActive))select.add(new Option(p.nome+' — '+p.codigo+' ('+p.unCompra+')',p.id));if([...select.options].some(x=>x.value===before))select.value=before;const options=$('gm-product-options');if(options){options.replaceChildren();for(const p of getCatalog().filter(M.isActive)){const o=document.createElement('option');o.value=p.nome+' — '+p.codigo;o.dataset.id=p.id;options.append(o);}}window.atualizarInfoConversaoMovimento?.();}
const originalOpen=window.abrirModalMovimentoEstoque;window.abrirModalMovimentoEstoque=function(type,id){try{originalOpen(type,id);fillProducts(id);$('gm-product-search').value='';}catch(e){showToast(e.message,'warning');}};
const select=$('mov-produto-select');if(select){const box=document.createElement('div');box.innerHTML='<label for="gm-product-search" class="block font-bold text-slate-700">Buscar produto cadastrado</label><input id="gm-product-search" list="gm-product-options" placeholder="Nome ou código do produto" class="w-full bg-slate-50 border border-slate-300 rounded-lg p-2"><datalist id="gm-product-options"></datalist><button class="gm-action" type="button" id="gm-new-product">+ Cadastrar novo produto</button>';select.parentElement.before(box);$('gm-product-search').onchange=()=>{try{const value=$('gm-product-search').value,matches=getCatalog().filter(M.isActive).filter(p=>p.nome+' — '+p.codigo===value||p.codigo===value);if(matches.length!==1)throw Error('Escolha um produto da lista ou cadastre um novo');select.value=matches[0].id;window.atualizarInfoConversaoMovimento?.();}catch(e){select.value='';showToast(e.message,'warning');}};$('gm-new-product').onclick=()=>{returnToMovement=true;window.abrirModalCadastrarProdutoFator();};}
const originalNew=window.abrirModalCadastrarProdutoFator;window.abrirModalCadastrarProdutoFator=function(){originalNew();$('prod-fator-estoque').value='0';$('prod-fator-fator-emb').value='1';productModal.classList.remove('hidden');productModal.style.display='flex';};
window.salvarProdutoFatorForm=function(event){event?.preventDefault();try{const before=localStorage.getItem(M.CATALOG),result=M.addProduct(getCatalog(),{nome:$('prod-fator-nome').value,codigo:$('prod-fator-codigo').value,segmento:$('prod-fator-segmento').value,unCompra:$('prod-fator-un-compra').value,unFator:$('prod-fator-un-fator').value,fatorEmb:$('prod-fator-fator-emb').value,precoCompra:$('prod-fator-preco-compra').value,precoVenda:$('prod-fator-preco-venda').value,estoqueCompra:$('prod-fator-estoque').value,tipoUso:$('ep-prod-type')?.value||'material',tamanho:$('ep-prod-size')?.value,ca:$('ep-prod-ca')?.value,validadeEpi:$('ep-prod-expiry')?.value,minimoEpi:$('ep-prod-min')?.value});if(result.product.tipoUso!=='material'){if(!window.martinsSalvarProdutoEpi)throw Error('Gestão de EPIs ainda não carregada');window.martinsSalvarProdutoEpi(result.rows,before);}else J.write(localStorage,M.CATALOG,result.rows,before);close('modal-cadastrar-produto-fator',true);window.renderTabelaProdutosFator?.();window.renderEstoqueDepositosMartins?.();if(returnToMovement){fillProducts(result.product.id);returnToMovement=false;}$('gm-product-search')&&($('gm-product-search').value=result.product.nome+' — '+result.product.codigo);refresh();window.renderEstoqueUniformes?.();window.dispatchEvent(new Event('martins-produtos-atualizados'));showToast('Produto cadastrado e disponível para seleção.');}catch(e){showToast('Produto não confirmado: '+e.message,'warning');}};
window.salvarMovimentoEstoqueForm=function(event){event?.preventDefault();try{const before=localStorage.getItem(M.CATALOG),rows=M.movement(getCatalog(),$('mov-produto-select').value,$('mov-tipo').value,$('mov-inp-qtd').value);J.write(localStorage,M.CATALOG,rows,before);window.fecharModalMovimentoEstoque();window.renderEstoqueDepositosMartins?.();showToast('Movimento de estoque registrado.');}catch(e){showToast(e.message,'warning');}};
const panel=document.createElement('section');panel.id='gm-obra';panel.innerHTML='<h3>Materiais da obra</h3><p class="gm-note">Requisições e registro de materiais utilizados ficam na Gestão. Estes lançamentos não aparecem no RDO.</p><p id="gm-work-name"></p><button id="gm-request" type="button">Requisitar materiais para esta obra</button><button id="gm-refresh" type="button">Atualizar produtos e consumos</button><h4 class="font-bold">Registrar material utilizado</h4><p class="gm-note">Registra quantidade e valor estimado na obra, sem baixa automática no estoque nem lançamento no fluxo de caixa.</p><div class="gm-grid"><label>Data<input id="gm-date" type="date"></label><label>Produto cadastrado<select id="gm-product"></select></label><label>Quantidade utilizada (unidade de compra)<input id="gm-quantity" type="number" step="any" min="0"></label><label>Valor por unidade de compra (R$)<input id="gm-price" type="number" step="0.01" min="0"></label></div><label>Observação<textarea id="gm-note" rows="2"></textarea></label><button id="gm-consume" type="button">Registrar consumo na Gestão</button><p id="gm-status" role="status"></p><p id="gm-total" class="font-bold"></p><div style="overflow:auto"><table><thead><tr><th>Data</th><th>Produto</th><th>Quantidade / unidade</th><th>Valor estimado</th><th>Observação</th><th>Registrado por</th></tr></thead><tbody id="gm-history"></tbody></table></div>';$('view-gestao')?.append(panel);const workAccess=document.createElement('button');workAccess.type='button';workAccess.className='gm-action';workAccess.textContent='Materiais da obra';workAccess.onclick=()=>{refresh();panel.scrollIntoView({block:'start',behavior:'smooth'});};$('gestao-obra-select')?.parentElement.append(workAccess);let consumptionSnapshot=null;const work=()=>$('gestao-obra-select')?.value;
function refresh(){try{$('gm-work-name').textContent='Obra selecionada: '+(work()||'selecione uma obra');const selected=$('gm-product').value;$('gm-product').replaceChildren(new Option('Selecione um produto',''));for(const p of getCatalog())$('gm-product').add(new Option(p.nome+' ('+p.unCompra+')',p.id));if([...$('gm-product').options].some(x=>x.value===selected))$('gm-product').value=selected;const rows=M.readConsumption(localStorage).filter(x=>x.obra===work());consumptionSnapshot=localStorage.getItem(M.CONSUMPTION);$('gm-history').replaceChildren();for(const r of rows.slice().reverse()){const tr=document.createElement('tr');for(const v of [r.data,r.produto,r.quantidade+' '+r.unidade,r.total.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),r.observacao||'',r.autor]){const td=document.createElement('td');td.textContent=String(v);tr.append(td);}$('gm-history').append(tr);}$('gm-total').textContent='Consumo registrado: '+rows.reduce((sum,r)=>sum+r.total,0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});}catch(e){$('gm-status').textContent=e.message;consumptionSnapshot=undefined;}}
$('gm-product').onchange=()=>{const p=getCatalog().find(x=>x.id===$('gm-product').value);$('gm-price').value=p?.precoCompra??'';};$('gm-request').onclick=()=>{if(!work()||!Object.hasOwn(dadosObras,work()))return;const modal=$('modal-novo-pedido-compra');$('ped-obra-select').value=work();window.currentItensPedido=[{material:'',qtd:1,unid:'un',aplicacao:'Canteiro de obras'}];window.renderItensPedidoTable?.();modal.classList.remove('hidden');modal.style.removeProperty('display');modal.style.zIndex='10040';};$('gm-refresh').onclick=refresh;$('gestao-obra-select')?.addEventListener('change',refresh);$('gm-date').value=new Date().toLocaleDateString('en-CA');$('gm-consume').onclick=()=>{try{if(consumptionSnapshot===undefined)throw Error('Atualize a lista antes de registrar');const entry=M.consumption({obra:work(),data:$('gm-date').value,produtoId:$('gm-product').value,quantidade:$('gm-quantity').value,valorUnitario:$('gm-price').value,observacao:$('gm-note').value,autor:currentLoggedUser?.nome},getCatalog(),Object.keys(dadosObras));M.record(localStorage,entry,consumptionSnapshot);$('gm-quantity').value='';$('gm-note').value='';refresh();$('gm-status').textContent='Consumo registrado somente na Gestão da Obra. RDO e saldo de estoque preservados.';}catch(e){$('gm-status').textContent=e.message;}};document.addEventListener('DOMContentLoaded',refresh);refresh();
})();
